patch.x-vmw-nsx-example-request:
Example 1:
----------
  PATCH https://&lt;policy-mgr&gt;/policy/api/v1/infra
  {
    "display_name": "infra",
    "path": "/infra",
    "relative_path": "infra",
    "connectivity_strategy": "NONE"
  }

Example 2:
----------
  # Below sample creates domain, groups, services and and security-policies in one call
  PATCH https://&lt;policy-mgr&gt;/policy/api/v1/infra
  {
    "resource_type":"Infra",
    "children": [
      {
        "resource_type":"ChildDomain",
        "Domain": {
          "id":"domain-test",
          "resource_type":"Domain",
          "description":"domain-test",
          "display_name":"domain-test",
          "children":[
            {
              "resource_type":"ChildGroup",
              "Group":{
                "resource_type":"Group",
                "description":"g1",
                "display_name":"g1",
                "id":"g1",
                "expression":[
                  {
                    "member_type":"VirtualMachine",
                    "value":"webvm",
                    "key":"Tag",
                    "operator":"EQUALS",
                    "resource_type":"Condition"
                  }
                ]
              }
            },
            {
              "resource_type":"ChildGroup",
              "Group":{
                "resource_type":"Group",
                "description":"g2",
                "display_name":"g2",
                "id":"g2",
                "expression":[
                  {
                    "member_type":"VirtualMachine",
                    "value":"dbvm",
                    "key":"Tag",
                    "operator":"EQUALS",
                    "resource_type":"Condition"
                  }
                ]
              }
            },
            {
              "resource_type":"ChildSecurityPolicy",
              "SecurityPolicy":{
                "id":"sp1",
                "resource_type":"SecurityPolicy",
                "description":"SecurityPolicy",
                "display_name":"SecurityPolicy",
                "rules":[
                  {
                    "resource_type":"Rule",
                    "description":"Rule",
                    "display_name":"r1",
                    "sequence_number":1,
                    "source_groups":[
                      "/infra/domains/domain-test/groups/g2"
                    ],
                    "destination_groups":[
                      "/infra/domains/domain-test/groups/g1"
                    ],
                    "services": [
                      "/infra/services/HTTP",
                      "/infra/services/AD_Server",
                      "/infra/services/CIM-HTTP"
                    ],
                    "action": "ALLOW"
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "resource_type":"ChildService",
        "Service": {
          "id":"s1",
          "resource_type":"Service",
          "description":"L4Service",
          "display_name":"L4Service",
          "service_entries": [
            {
              "resource_type":"L4PortSetServiceEntry",
              "display_name":"L4ServiceEntry",
              "destination_ports": [
                "464"
              ],
              "l4_protocol":"TCP"
            }
          ]
        }
      }
    ]
  }

Example 3:
----------
  #Hierarchical delete example
  #Below example deletes domain-test including all its
  #children(groups, security policies, services)
  PATCH https://&lt;policy-mgr&gt;/policy/api/v1/infra
  {
    "resource_type":"Infra",
    "children":[
      {
        "resource_type":"ChildDomain",
        "marked_for_delete": true,
        "Domain":{
          "id":"domain-test",
          "resource_type":"Domain"
        }
      }
    ]
  }

Example 4:
----------
  #Example using ChildResourceReference in hierarchical API
  #Below example updates group g1 in 'domain-test' without updating domain and without
